        if (finished) return;
        finished = true;
        clearTimeout(quietTimer);
        clearTimeout(maximumTimer);
        observer.disconnect();
        resolve(undefined);
      };
      const maximumTimer = setTimeout(done, 4_000);
      observer.observe(root, { childList: true, subtree: true, characterData: true, attributes: true });
