  const clip = boards[1];
  expect(clip).toMatchObject({ type: "board", clipContent: true, name: "card", opacity: 0.5 });
  expect(clip.pluginData).toMatchObject({ source: "body > div > section" });
  expect(clip.children?.map((child) => child.type)).toEqual(["text"]);
});

